mapper.select:
SELECT p.*,
(CASE WHEN EXISTS (SELECT 1 FROM items_category c WHERE c.parent_id = p.category_id LIMIT 1) THEN 1 ELSE 0 END) AS has_children
FROM items_category p

	AND p.company_id = #{companyId}
	AND p.is_main_category = #{isMainCategory}
	AND p.distributor_id = #{distributorId}

		AND p.parent_id = #{parentIdRaw}


		AND p.category_level = #{categoryLevelRaw}


		AND p.is_show_front = #{isShowFront}


ORDER BY p.sort DESC, p.created ASC

	LIMIT #{offset}, #{limit}
